package com.portfolio.assetory.inquiry;
import java.time.LocalDateTime;import java.util.List;import org.springframework.dao.DataIntegrityViolationException;import org.springframework.data.domain.*;import org.springframework.http.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.bind.annotation.*;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import com.portfolio.assetory.global.auth.CurrentUserId;import com.portfolio.assetory.global.exception.*;import com.portfolio.assetory.global.response.ApiResponse;import com.portfolio.assetory.inquiry.domain.*;import com.portfolio.assetory.inquiry.repository.*;import com.portfolio.assetory.member.repository.UserRepository;import com.portfolio.assetory.product.repository.ProductRepository;
@RestController @RequestMapping("/api/inquiries/rooms") public class InquiryController{private final InquiryService service;public InquiryController(InquiryService s){service=s;}@PostMapping public ResponseEntity<ApiResponse<RoomResponse>> create(@CurrentUserId Long u,@Valid @RequestBody CreateRequest r){InquiryService.Created c=service.create(u,r.productId());return ResponseEntity.status(c.created()?HttpStatus.CREATED:HttpStatus.OK).body(ApiResponse.success(RoomResponse.from(c.room())));}@GetMapping public ResponseEntity<ApiResponse<RoomListResponse>> list(@CurrentUserId Long u,@RequestParam(defaultValue="0")int p,@RequestParam(defaultValue="20")int s){return ResponseEntity.ok(ApiResponse.success(service.list(u,p,s)));}@GetMapping("/{id}")public ResponseEntity<ApiResponse<RoomDetailResponse>> detail(@CurrentUserId Long u,@PathVariable Long id){return ResponseEntity.ok(ApiResponse.success(service.detail(u,id)));}@PostMapping("/{id}/messages")public ResponseEntity<ApiResponse<MessageResponse>> send(@CurrentUserId Long u,@PathVariable Long id,@Valid @RequestBody SendRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(ApiResponse.success(service.send(u,id,r.content())));}@GetMapping("/{id}/messages")public ResponseEntity<ApiResponse<List<MessageResponse>>> messages(@CurrentUserId Long u,@PathVariable Long id){return ResponseEntity.ok(ApiResponse.success(service.messages(u,id)));}@PatchMapping("/{id}/read")public ResponseEntity<ApiResponse<ReadResponse>> read(@CurrentUserId Long u,@PathVariable Long id){return ResponseEntity.ok(ApiResponse.success(service.read(u,id)));}@PatchMapping("/{id}/close")public ResponseEntity<ApiResponse<RoomResponse>> close(@CurrentUserId Long u,@PathVariable Long id){return ResponseEntity.ok(ApiResponse.success(RoomResponse.from(service.close(u,id))));}public record CreateRequest(@NotNull Long productId){}public record SendRequest(@NotBlank @Size(max=2000)String content){}public record ReadResponse(int readCount){}public record RoomResponse(Long roomId,Long productId,String productName,Long buyerId,String buyerNickname,Long sellerId,String sellerNickname,String status,LocalDateTime createdAt,LocalDateTime closedAt){static RoomResponse from(InquiryRoom r){return new RoomResponse(r.getId(),r.getProduct().getId(),r.getProduct().getName(),r.getBuyer().getId(),r.getBuyer().getNickname(),r.getSeller().getId(),r.getSeller().getNickname(),r.getStatus().name(),r.getCreatedAt(),r.getClosedAt());}}public record RoomListResponse(List<RoomResponse> rooms,int page,int totalPages){}public record RoomDetailResponse(RoomResponse room,List<MessageResponse> messages){ }public record MessageResponse(Long messageId,Long senderId,String senderNickname,String content,LocalDateTime sentAt,LocalDateTime readAt){static MessageResponse from(InquiryMessage m){return new MessageResponse(m.getId(),m.getSender().getId(),m.getSender().getNickname(),m.getContent(),m.getSentAt(),m.getReadAt());}}}
@Service @Transactional class InquiryService{private final InquiryRoomRepository rooms;private final InquiryMessageRepository messages;private final ProductRepository products;private final UserRepository users;InquiryService(InquiryRoomRepository r,InquiryMessageRepository m,ProductRepository p,UserRepository u){rooms=r;messages=m;products=p;users=u;}record Created(InquiryRoom room,boolean created){}Created create(Long u,Long productId){var product=products.findById(productId).orElseThrow(()->new BusinessException(ErrorCode.PRODUCT_NOT_FOUND));if(product.getSeller().getId().equals(u))throw new BusinessException(ErrorCode.FORBIDDEN);var existing=rooms.findByBuyerIdAndProductIdAndSellerId(u,productId,product.getSeller().getId());if(existing.isPresent())return new Created(existing.get(),false);var buyer=users.findById(u).orElseThrow(()->new BusinessException(ErrorCode.USER_NOT_FOUND));try{return new Created(rooms.saveAndFlush(InquiryRoom.create(buyer,product)),true);}catch(DataIntegrityViolationException e){return new Created(rooms.findByBuyerIdAndProductIdAndSellerId(u,productId,product.getSeller().getId()).orElseThrow(()->e),false);}}InquiryController.RoomListResponse list(Long u,int p,int s){if(p<0||s<1||s>100)throw new BusinessException(ErrorCode.INVALID_INPUT);Page<InquiryRoom> page=rooms.findAllForUser(u,PageRequest.of(p,s,Sort.by(Sort.Direction.DESC,"createdAt")));return new InquiryController.RoomListResponse(page.getContent().stream().map(InquiryController.RoomResponse::from).toList(),page.getNumber(),page.getTotalPages());}InquiryController.RoomDetailResponse detail(Long u,Long id){InquiryRoom r=room(id,u);return new InquiryController.RoomDetailResponse(InquiryController.RoomResponse.from(r),messages.findAllForRoom(id).stream().map(InquiryController.MessageResponse::from).toList());}InquiryController.MessageResponse send(Long u,Long id,String content){InquiryRoom r=room(id,u);if(r.getStatus()==InquiryRoomStatus.CLOSED)throw new BusinessException(ErrorCode.INQUIRY_ROOM_CLOSED);var sender=users.findById(u).orElseThrow(()->new BusinessException(ErrorCode.USER_NOT_FOUND));return InquiryController.MessageResponse.from(messages.save(InquiryMessage.send(r,sender,content)));}List<InquiryController.MessageResponse> messages(Long u,Long id){room(id,u);return messages.findAllForRoom(id).stream().map(InquiryController.MessageResponse::from).toList();}InquiryController.ReadResponse read(Long u,Long id){room(id,u);return new InquiryController.ReadResponse(messages.markReadByRoomIdAndNotSender(id,u));}InquiryRoom close(Long u,Long id){InquiryRoom r=room(id,u);if(r.getStatus()==InquiryRoomStatus.CLOSED)throw new BusinessException(ErrorCode.INQUIRY_ROOM_CLOSED);r.close();return r;}private InquiryRoom room(Long id,Long u){return rooms.findForParticipant(id,u).orElseThrow(()->new BusinessException(ErrorCode.INQUIRY_ROOM_NOT_FOUND));}}
